@Override
public List<Detector> getDetectors() {
    if (loader != null) {
        List<Detector> detectors = loader.loadDynamicServiceProviders(Detector.class);
        detectors.addAll(super.getDetectors());
        return detectors;
    } else {
        return super.getDetectors();
    }
}
